-- Preserve legacy reviews; absent authority/authentication evidence remains NULL.
CREATE TABLE IF NOT EXISTS atlas_proposal_reviews (id TEXT PRIMARY KEY,proposal_id TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')),reviewer_id TEXT NOT NULL,reviewed_at INTEGER NOT NULL,reviewed_decision_fingerprint TEXT,basis_code TEXT NOT NULL,review_note TEXT,reviewer_role_code TEXT,reviewer_authority_source TEXT,review_auth_assurance_type TEXT,review_auth_session_id TEXT,review_mfa_verified_at INTEGER,review_hash_version INTEGER,review_sequence INTEGER,previous_review_hash TEXT,review_hash TEXT);
